<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?>
<div id="wrapper"><div class="content"><?php $this->load->view('feedbacks/_navigation'); ?><div class="row"><div class="col-md-12"><div class="panel_s"><div class="panel-body">
<div class="tw-flex tw-items-center tw-justify-between"><div><h4 class="no-margin"><?php echo _l('fb_reports'); ?></h4><p class="text-muted mtop5"><?php echo _l('fb_reports_intro'); ?></p></div><a class="btn btn-default" href="<?php echo admin_url('feedbacks'); ?>"><?php echo _l('back'); ?></a></div>
