<div class="row mtop20"><?php foreach ([[_l('fb_total_questionnaires'),$total_questionnaires],[_l('fb_active_questionnaires'),$active_questionnaires],[_l('fb_total_participation'),$total_participation]] as $metric) { ?><div class="col-md-4"><div class="panel_s"><div class="panel-body"><p class="text-muted"><?php echo $metric[0]; ?></p><h2 class="bold"><?php echo (int)$metric[1]; ?></h2></div></div></div><?php } ?></div>
