<?php if (!empty($question_breakdown)) { ?><h4 class="mtop20"><?php echo _l('fb_answer_breakdown'); ?></h4><table class="table table-bordered"><thead><tr><th><?php echo _l('fb_answer'); ?></th><th><?php echo _l('fb_count'); ?></th></tr></thead><tbody><?php foreach($question_breakdown as $answer){ ?><tr><td><?php echo html_escape((string)$answer['answer']); ?></td><td><?php echo (int)$answer['total']; ?></td></tr><?php } ?></tbody></table><?php } ?>
